function DocTxt($id,$which){$p='{"documentId":"'+$id+'","includeTabsContent":true}';$raw=gws docs documents get --params $p --format json | Out-String;$d=$raw|ConvertFrom-Json;$ti=0;$si=0;for($i=0;$i -lt $d.tabs.Count;$i++){if($d.tabs[$i].tabProperties.title -eq 'Transcript'){$ti=$i};if($d.tabs[$i].tabProperties.title -eq 'Full notes'){$si=$i}};$ix=if($which -eq 'transcript'){$ti}else{$si};$out=[System.Collections.Generic.List[string]]::new();foreach($block in $d.tabs[$ix].documentTab.body.content){$parts=[System.Collections.Generic.List[string]]::new();foreach($el in $block.paragraph.elements){if($el.textRun){$parts.Add($el.textRun.content)}};if($parts.Count){$out.Add(($parts -join ''))}};return ($out -join '')}
$spec=@(
@{s='sofia';d='2026-09-15';id='1JUYdkLlWfJEeFqDpvRZ1TgkCLvHkbpWIuXOhddEG6oM'},@{s='sofia';d='2026-09-18';id='1ANFhV5xXI9U-L9DWK3h76ZRYZrfjyw6MdquXDTRafc8'},@{s='sofia';d='2026-09-23';id='1O-gl6f5tMIXUDXKaYs3LqNUNmA1H_T4kAjsX2mW7OSI'},@{s='charles-moore';d='2026-09-14';id='1TNtcJz-qWMg_GNm4duV37AqYgb8SVxbZ_D6u4cFirEU'},@{s='yahunatan-zetvy';d='2026-09-02';id='126ktrgakkCCGa0RUCE5ejsJzU1AaptVZSJA9eVodacs'},@{s='yahunatan-zetvy';d='2026-09-16';id='1ZPdB1LBKXC-bVtxSJikWvwe0cC04Q9fHWl6no_Cggeg'}
)
foreach($x in $spec){foreach($which in 'transcript','summary'){$t=DocTxt $x.id $which;Set-Content -LiteralPath "temp_${which}_$($x.s)_$($x.d).txt" -Value $t -NoNewline};"done $($x.s) $($x.d)"}
